        ('%yerba%', '%yerba%', '(?:(?:^|[^[:alpha:]])[yýÿ][eèéêë]rb[aàáâãäå](?!less)(?![- ]?free(?![- ]?(?:range|run|roam))(?![[:space:](-]+(?:from|of)(?![[:alpha:]]))(?:[^[:alpha:]]|$)))', NULL),
        ('%yoghurt%', '%yoghurt%', '(?:(?:^|[^[:alpha:]])[yýÿ][oòóôõöø]gh[uùúûü]rt(?!less)(?![- ]?free(?![- ]?(?:range|run|roam))(?![[:space:](-]+(?:from|of)(?![[:alpha:]]))(?:[^[:alpha:]]|$)))', '(?:^|[^[:alpha:]])(?:[cç][oòóôõöø][cç][oòóôõöø][nñ][uùúûü]t(?:[''’]?s[''’]?)?[[:space:](-]+[yýÿ][oòóôõöø]gh[uùúûü]rt|s[oòóôõöø][yýÿ](?:[''’]?s[''’]?)?[[:space:](-]+[yýÿ][oòóôõöø]gh[uùúûü]rt)(?:s|es|[''’]s)?(?![[:alpha:]])'),
        ('%yogurt%', '%yogurt%', '(?:(?:^|[^[:alpha:]])[yýÿ][oòóôõöø]g[uùúûü]rt(?!less)(?![- ]?free(?![- ]?(?:range|run|roam))(?![[:space:](-]+(?:from|of)(?![[:alpha:]]))(?:[^[:alpha:]]|$)))', '(?:^|[^[:alpha:]])(?:[cç][oòóôõöø][cç][oòóôõöø][nñ][uùúûü]t(?:[''’]?s[''’]?)?[[:space:](-]+[yýÿ][oòóôõöø]g[uùúûü]rt|[aàáâãäå]lm[oòóôõöø][nñ]d(?:[''’]?s[''’]?)?[[:space:](-]+[yýÿ][oòóôõöø]g[uùúûü]rt|s[oòóôõöø][yýÿ](?:[''’]?s[''’]?)?[[:space:](-]+[yýÿ][oòóôõöø]g[uùúûü]rt)(?:s|es|[''’]s)?(?![[:alpha:]])'),
